import json
from collections import Counter

with open('fees.json') as f:
    fees = json.load(f)

account_type = 'R'
mcc = 5942
monthly_volume = '100k-1m'
monthly_fraud_level = '>8.3%'
is_credit = True
intracountry = False

def matches_list(rule_list, actual):
    if rule_list is None or rule_list == []:
        return True
    return actual in rule_list

def matches_bool(rule_val, actual):
    if rule_val is None:
        return True
    return rule_val == actual

def matches_intracountry(rule_val, actual):
    if rule_val is None:
        return True
    return bool(rule_val) == actual

def find_matching_rules(aci, capture_delay):
    matched = []
    for r in fees:
        if r['card_scheme'] is None:
            continue
        if not matches_list(r['account_type'], account_type):
            continue
        if capture_delay is not None and r['capture_delay'] is not None and r['capture_delay'] != capture_delay:
            continue
        if r['monthly_volume'] is not None and r['monthly_volume'] != monthly_volume:
            continue
        if r['monthly_fraud_level'] is not None and r['monthly_fraud_level'] != monthly_fraud_level:
            continue
        if not matches_list(r['merchant_category_code'], mcc):
            continue
        if not matches_bool(r['is_credit'], is_credit):
            continue
        if not matches_list(r['aci'], aci):
            continue
        if not matches_intracountry(r['intracountry'], intracountry):
            continue
        matched.append(r)
    return matched

# For ACI=G, test with different capture_delay handling
for cd in ['<3', None]:
    m = find_matching_rules('G', cd)
    print(f"ACI=G, capture_delay filter={cd}: {len(m)} rules")
    for r in m:
        print(f"   ID={r['ID']} scheme={r['card_scheme']} cd={r['capture_delay']} fixed={r['fixed_amount']} rate={r['rate']} aci={r['aci']}")
    print()

